"""Attempt a one-frame visible left-arm gesture on an attached Native walker.

Bone command/readback is separate from source-video visibility and legal signal
appropriateness. The physical rider-bike attachment needs a local CARLA trial.
"""


BONE = 'crl_arm__L'


def _bone(walker):
    for item in walker.get_bones().bone_transforms:
        if item.name == BONE:
            return item
    raise ValueError('Native rider has no left upper-arm bone')


class RiderArm:
    def __init__(self, walker, carla_module):
        self.walker = walker
        self.carla = carla_module
        self.neutral = _bone(walker).relative
        self.raised = False

    def set_signal(self, raised):
        if type(raised) is not bool:
            raise ValueError('Rider signal command must be boolean')
        if raised:
            rotation = self.neutral.rotation
            pose = self.carla.Transform(
                self.neutral.location,
                self.carla.Rotation(pitch=rotation.pitch,
                                    yaw=rotation.yaw,
                                    roll=rotation.roll + 70))
            control = self.carla.WalkerBoneControlIn([(BONE, pose)])
            self.walker.set_bones(control)
            self.walker.blend_pose(1)
        else:
            self.walker.blend_pose(0)
        self.raised = raised

    def readback(self):
        observed = _bone(self.walker).relative.rotation.roll
        return {'bone': BONE, 'commanded_raised': self.raised,
                'relative_roll_deg': float(observed),
                'neutral_relative_roll_deg': float(self.neutral.rotation.roll)}

"""Select a connected roadway approach and left turn; feedback steer a bicycle."""

from math import atan2, cos, hypot, radians, sin


def _yaw_delta(first, last):
    angle = radians(last - first)
    return atan2(sin(angle), cos(angle)) * 180 / 3.141592653589793


def select_left_turn(world_map, *, step_m=1.5):
    for spawn in world_map.get_spawn_points():
        start = world_map.get_waypoint(spawn.location)
        if start is None or start.is_junction:
            continue
        approach = [start]
        for _ in range(8):
            options = [w for w in approach[-1].next(step_m)
                       if w.road_id == start.road_id and
                       w.lane_id == start.lane_id]
            if len(options) != 1:
                break
            approach.append(options[0])
        if len(approach) != 9:
            continue
        frontier = [(approach[-1], [])]
        for _ in range(16):
            next_frontier = []
            for waypoint, path in frontier:
                for nxt in waypoint.next(step_m):
                    if any(nxt is old for old in path):
                        continue
                    expanded = path + [nxt]
                    delta = _yaw_delta(start.transform.rotation.yaw,
                                       nxt.transform.rotation.yaw)
                    if 65 <= delta <= 130 and len(expanded) >= 6:
                        return approach + expanded
                    if len(next_frontier) < 32:
                        next_frontier.append((nxt, expanded))
            frontier = next_frontier
            if not frontier:
                break
    raise ValueError('No connected Native roadway left-turn route')


def control(position_xy, heading_xy, velocity_xy, target_xy, *, target_speed_mps=3):
    dx, dy = target_xy[0] - position_xy[0], target_xy[1] - position_xy[1]
    distance = hypot(dx, dy)
    if distance < .15:
        raise ValueError('Rider route target collapsed')
    hx, hy = heading_xy
    norm = hypot(hx, hy)
    if norm < 1e-6:
        raise ValueError('Rider heading undefined')
    angle = atan2((hx * dy - hy * dx) / norm,
                  (hx * dx + hy * dy) / norm)
    speed = hypot(*velocity_xy)
    return {'steer': max(-.5, min(.5, 1.1 * angle)),
            'throttle': max(0, min(.55, .3 * (target_speed_mps - speed))),
            'brake': max(0, min(.5, .25 * (speed - target_speed_mps)))}

"""Four synchronized original RGB source streams for rider probes."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-24, 0, 8), (-8, 0, 0), (1920, 1080), 95),
    "approach": ((-2.5, 3.5, 2.2), (-5, 0, 0), (1280, 720), 90),
    "reference_corner": ((-2.5, -3.5, 2.2), (-5, 0, 0), (1280, 720), 100),
    "driver_reference": ((-2, 0, 1.8), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown rider source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior exposure camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original rider camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Rider source encoder failed")


class RiderCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named rider source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original rider camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original rider camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Rider source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original rider source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original rider camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

"""Join original rider turn motion to reviewed source-video signal frames.

This measures whether a visible signal was observed before turn onset, including
one-frame signals. It does not decide appropriateness, safety or exceptions.
"""

from hashlib import sha256
import json
from math import atan2, cos, isfinite, radians, sin
from pathlib import Path


DEVICES = ('bicycle', 'electric_bicycle', 'electric_scooter')


def _rows(path, name):
    path = Path(path)
    if not path.is_file() or not path.read_bytes():
        raise ValueError('Missing original source: ' + name)
    raw = path.read_bytes()
    try:
        return [json.loads(line) for line in raw.splitlines()], sha256(raw).hexdigest()
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid original source: ' + name) from error


def measure(motion_path, review_path, context_path, video_path):
    motion, motion_sha = _rows(motion_path, 'rider_motion.jsonl')
    reviews, review_sha = _rows(review_path, 'rider_signal_review.jsonl')
    context_path, video_path = Path(context_path), Path(video_path)
    if not context_path.is_file() or not context_path.read_bytes():
        raise ValueError('Missing original source: rider_context.json')
    if not video_path.is_file() or not video_path.read_bytes():
        raise ValueError('Missing original source: driver_reference.mkv')
    context_raw, video_sha = context_path.read_bytes(), sha256(video_path.read_bytes()).hexdigest()
    try:
        context = json.loads(context_raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid original rider context') from error
    if len(motion) < 3 or len(motion) != len(reviews):
        raise ValueError('Original rider motion/signal review incomplete')
    if context.get('device_type') not in DEVICES or not context.get('device_type_source'):
        raise ValueError('Rider device type needs original source')
    if context.get('on_roadway') is not True or not context.get('roadway_source'):
        raise ValueError('Roadway activation needs original source')
    for key in ('designated_turn_lane', 'both_hands_required_for_safety'):
        item = context.get(key)
        if not isinstance(item, dict) or 'value' not in item:
            raise ValueError('Signal exception context missing: ' + key)
        value, source = item['value'], item.get('source_ref')
        if value is not None and (type(value) is not bool or not isinstance(source, str) or not source):
            raise ValueError('Known signal exception needs source: ' + key)
        if value is None and source is not None:
            raise ValueError('Unknown signal exception cannot cite verdict: ' + key)
    observations = []
    prior = None
    initial_yaw = None
    rider_id = context.get('rider_id')
    if not rider_id:
        raise ValueError('Original rider identity missing')
    for motion_row, review in zip(motion, reviews):
        frame, time_s = motion_row.get('frame'), motion_row.get('time_s')
        if type(frame) is not int or type(time_s) not in (int, float) or not isfinite(time_s):
            raise ValueError('Original rider frame/time invalid')
        if prior is not None and (frame != prior[0] + 1 or abs(time_s - prior[1] - .05) > 1e-4):
            raise ValueError('Original rider frames are not joined at 20 Hz')
        prior = frame, time_s
        if (review.get('frame'), review.get('time_s'), review.get('rider_id')) != (frame, time_s, rider_id):
            raise ValueError('Original signal/video frame or rider join failed')
        if review.get('source_video_sha256') != video_sha:
            raise ValueError('Signal review no longer binds retained video')
        visible = review.get('visible_signal')
        if visible is not None and type(visible) is not bool:
            raise ValueError('Signal visibility review invalid')
        signal = review.get('signal_type')
        if signal not in ('left_arm', 'right_arm', 'none', 'unknown'):
            raise ValueError('Signal type review invalid')
        if visible is True and signal not in ('left_arm', 'right_arm'):
            raise ValueError('Visible signal needs observed arm direction')
        try:
            yaw = float(motion_row['rider_yaw_deg'])
        except (KeyError, TypeError, ValueError) as error:
            raise ValueError('Original rider yaw missing') from error
        if not isfinite(yaw):
            raise ValueError('Original rider yaw invalid')
        if initial_yaw is None:
            initial_yaw = yaw
        delta = atan2(sin(radians(yaw - initial_yaw)), cos(radians(yaw - initial_yaw))) * 180 / 3.141592653589793
        observations.append({'frame': frame, 'time_s': time_s,
                             'heading_change_deg': delta,
                             'visible_signal': visible,
                             'signal_type': signal})
    onset = next((i for i, row in enumerate(observations)
                  if abs(row['heading_change_deg']) > .5), None)
    if onset is None or onset == 0:
        raise ValueError('No measured rider turn onset')
    before = observations[:onset]
    return {'format': 'worker-rider-turn-signal-observation',
            'sources': {'rider_motion.jsonl': motion_sha,
                        'rider_signal_review.jsonl': review_sha,
                        'rider_context.json': sha256(context_raw).hexdigest(),
                        video_path.name: video_sha},
            'device_type': context['device_type'],
            'turn_onset_frame': observations[onset]['frame'],
            'pre_turn_visible_signal_frames': [row['frame'] for row in before
                                               if row['visible_signal'] is True],
            'pre_turn_signal_observation_complete': all(row['visible_signal'] is not None
                                                        for row in before),
            'signal_exception_context': {key: context[key] for key in
                                         ('designated_turn_lane', 'both_hands_required_for_safety')},
            'observations': observations,
            'appropriate_signal_legal_judgment': None,
            'reasonable_safety_legal_judgment': None,
            'both_hands_safety_legal_judgment': None}

from pathlib import Path
from types import SimpleNamespace as NS
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from rider_camera import CAMERAS, RiderCameraCapture


class Sensor:
    def listen(self, callback):
        self.callback = callback

    def stop(self):
        pass

    def destroy(self):
        self.destroyed = True


class World:
    def __init__(self):
        self.sensors = []

    def get_blueprint_library(self):
        return NS(find=lambda _: NS(set_attribute=lambda *args: None))

    def spawn_actor(self, blueprint, transform, attach_to):
        sensor = Sensor()
        self.sensors.append(sensor)
        return sensor


class Sink:
    def __init__(self):
        self.frames = []

    def write(self, image):
        self.frames.append(image.frame)


class CameraTests(unittest.TestCase):
    def test_four_named_frames_and_missing_frame_rejection(self):
        world = World()
        carla = NS(Location=lambda *values: values, Rotation=lambda *values: values,
                   Transform=lambda location, rotation: (location, rotation))
        sinks = {name: Sink() for name in CAMERAS}
        capture = RiderCameraCapture(world, carla, object(), sinks)
        self.assertEqual(len(world.sensors), 4)
        for sensor, (name, spec) in zip(world.sensors, CAMERAS.items()):
            width, height = spec[2]
            sensor.callback(NS(frame=20, width=width, height=height))
        capture.wait_for_frame(20, timeout_s=.01)
        self.assertEqual(capture.verify([20]), {name: 1 for name in CAMERAS})
        with self.assertRaisesRegex(ValueError, 'Missing or extra'):
            capture.verify([20, 21])
        capture.close()
        self.assertTrue(all(sensor.destroyed for sensor in world.sensors))


if __name__ == '__main__':
    unittest.main()

"""Native lane readback and source-review join for the no-signal turn-lane case."""
from hashlib import sha256
import json
from pathlib import Path


def capture_lane(world_map, location, frame, time_s):
    waypoint = world_map.get_waypoint(location)
    if waypoint is None:
        raise ValueError('No Native roadway waypoint at rider')
    left = getattr(waypoint, 'left_lane_marking', None)
    right = getattr(waypoint, 'right_lane_marking', None)
    return {'frame': frame, 'time_s': time_s, 'road_id': waypoint.road_id,
            'lane_id': waypoint.lane_id, 'lane_type': str(waypoint.lane_type),
            'is_junction': bool(waypoint.is_junction),
            'left_marking_type': str(left.type) if left else None,
            'right_marking_type': str(right.type) if right else None,
            'designation_from_map': None}


def _rows(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def measure(attempt):
    root = Path(attempt)
    names = ('video_frames.jsonl', 'lane_waypoint_readback.jsonl',
             'turn_lane_marking_review.jsonl', 'driver_reference.mkv')
    paths = {name: root / name for name in names}
    for name, path in paths.items():
        if not path.is_file() or not path.read_bytes():
            raise ValueError('Missing required source: ' + name)
    mapping, lanes, reviews = (_rows(paths[name]) for name in names[:3])
    if len(mapping) < 3 or len(mapping) != len(lanes) or len(mapping) != len(reviews):
        raise ValueError('Turn-lane original frame lengths differ')
    video_sha = sha256(paths['driver_reference.mkv'].read_bytes()).hexdigest()
    visible_frames = []
    for index, (frame, lane, review) in enumerate(zip(mapping, lanes, reviews)):
        identity = frame.get('carla_frame'), frame.get('time_s')
        if (frame.get('video_frame') != index or
                (lane.get('frame'), lane.get('time_s')) != identity or
                (review.get('frame'), review.get('time_s')) != identity):
            raise ValueError('Turn-lane original frame identity differs')
        if review.get('source_video_sha256') != video_sha:
            raise ValueError('Stale turn-lane pixel review')
        visible = review.get('visible_turn_lane_designation')
        if visible is not None and type(visible) is not bool:
            raise ValueError('Invalid turn-lane review')
        if visible is True:
            visible_frames.append(frame['carla_frame'])
    return {'lane_ids': sorted(set(row['lane_id'] for row in lanes)),
            'road_ids': sorted(set(row['road_id'] for row in lanes)),
            'visible_designation_frames': visible_frames,
            'designation_review_complete': all(row['visible_turn_lane_designation'] is not None for row in reviews),
            'designated_turn_lane_confirmed': None,
            'legal_signal_exception_judgment': None,
            'sources': {name: sha256(path.read_bytes()).hexdigest() for name, path in paths.items()}}
